//! Two `Mob`s, field by field (generated by `gen/groups.py`).
use crate::mobs::Mob;

fn d(out: &mut Vec<String>, name: &str, a: String, b: String) {
    if a != b {
        out.push(format!("{name}: {a} / {b}"));
    }
}
pub fn differences(a: &Mob, b: &Mob) -> Vec<String> {
    let mut out = Vec::new();
    d(&mut out, "id", format!("{:?}", a.id), format!("{:?}", b.id));
    d(&mut out, "position", format!("{:?}", a.position), format!("{:?}", b.position));
    d(&mut out, "previous", format!("{:?}", a.previous), format!("{:?}", b.previous));
    d(&mut out, "velocity", format!("{:?}", a.velocity), format!("{:?}", b.velocity));
    d(&mut out, "yaw", format!("{:?}", a.yaw), format!("{:?}", b.yaw));
    d(&mut out, "previous_yaw", format!("{:?}", a.previous_yaw), format!("{:?}", b.previous_yaw));
    d(&mut out, "body_yaw", format!("{:?}", a.body_yaw), format!("{:?}", b.body_yaw));
    d(&mut out, "previous_body_yaw", format!("{:?}", a.previous_body_yaw), format!("{:?}", b.previous_body_yaw));
    d(&mut out, "head_yaw", format!("{:?}", a.head_yaw), format!("{:?}", b.head_yaw));
    d(&mut out, "previous_head_yaw", format!("{:?}", a.previous_head_yaw), format!("{:?}", b.previous_head_yaw));
    d(&mut out, "head_pitch", format!("{:?}", a.head_pitch), format!("{:?}", b.head_pitch));
    d(&mut out, "previous_head_pitch", format!("{:?}", a.previous_head_pitch), format!("{:?}", b.previous_head_pitch));
    d(&mut out, "on_ground", format!("{:?}", a.on_ground), format!("{:?}", b.on_ground));
    d(&mut out, "horizontal_collision", format!("{:?}", a.horizontal_collision), format!("{:?}", b.horizontal_collision));
    d(&mut out, "vertical_collision_below", format!("{:?}", a.vertical_collision_below), format!("{:?}", b.vertical_collision_below));
    d(&mut out, "needs_sync", format!("{:?}", a.needs_sync), format!("{:?}", b.needs_sync));
    d(&mut out, "sync_position", format!("{:?}", a.sync_position), format!("{:?}", b.sync_position));
    d(&mut out, "fall_distance", format!("{:?}", a.fall_distance), format!("{:?}", b.fall_distance));
    d(&mut out, "stuck_multiplier", format!("{:?}", a.stuck_multiplier), format!("{:?}", b.stuck_multiplier));
    d(&mut out, "piston", format!("{:?}", a.piston), format!("{:?}", b.piston));
    d(&mut out, "supporting", format!("{:?}", a.supporting), format!("{:?}", b.supporting));
    d(&mut out, "climbing", format!("{:?}", a.climbing), format!("{:?}", b.climbing));
    d(&mut out, "on_climbable", format!("{:?}", a.on_climbable), format!("{:?}", b.on_climbable));
    d(&mut out, "no_gravity", format!("{:?}", a.no_gravity), format!("{:?}", b.no_gravity));
    d(&mut out, "no_physics", format!("{:?}", a.no_physics), format!("{:?}", b.no_physics));
    d(&mut out, "pushed", format!("{:?}", a.pushed), format!("{:?}", b.pushed));
    d(&mut out, "limb_position", format!("{:?}", a.limb_position), format!("{:?}", b.limb_position));
    d(&mut out, "limb_speed", format!("{:?}", a.limb_speed), format!("{:?}", b.limb_speed));
    d(&mut out, "previous_limb_speed", format!("{:?}", a.previous_limb_speed), format!("{:?}", b.previous_limb_speed));
    d(&mut out, "health", format!("{:?}", a.health), format!("{:?}", b.health));
    d(&mut out, "hurt_time", format!("{:?}", a.hurt_time), format!("{:?}", b.hurt_time));
    d(&mut out, "invulnerable", format!("{:?}", a.invulnerable), format!("{:?}", b.invulnerable));
    d(&mut out, "invulnerable_time", format!("{:?}", a.invulnerable_time), format!("{:?}", b.invulnerable_time));
    d(&mut out, "death_time", format!("{:?}", a.death_time), format!("{:?}", b.death_time));
    d(&mut out, "impulse_grace_time", format!("{:?}", a.impulse_grace_time), format!("{:?}", b.impulse_grace_time));
    d(&mut out, "absorption", format!("{:?}", a.absorption), format!("{:?}", b.absorption));
    d(&mut out, "last_hurt", format!("{:?}", a.last_hurt), format!("{:?}", b.last_hurt));
    d(&mut out, "dealt_absorbed", format!("{:?}", a.dealt_absorbed), format!("{:?}", b.dealt_absorbed));
    d(&mut out, "last_damage", format!("{:?}", a.last_damage), format!("{:?}", b.last_damage));
    d(&mut out, "accepted_hit", format!("{:?}", a.accepted_hit), format!("{:?}", b.accepted_hit));
    d(&mut out, "death_canceled", format!("{:?}", a.death_canceled), format!("{:?}", b.death_canceled));
    d(&mut out, "last_direct", format!("{:?}", a.last_direct), format!("{:?}", b.last_direct));
    d(&mut out, "attacker_aim", format!("{:?}", a.attacker_aim), format!("{:?}", b.attacker_aim));
    d(&mut out, "creative_attacker", format!("{:?}", a.creative_attacker), format!("{:?}", b.creative_attacker));
    d(&mut out, "projectile_motion", format!("{:?}", a.projectile_motion), format!("{:?}", b.projectile_motion));
    d(&mut out, "invulnerable_flag", format!("{:?}", a.invulnerable_flag), format!("{:?}", b.invulnerable_flag));
    d(&mut out, "combat", format!("{:?}", a.combat), format!("{:?}", b.combat));
    d(&mut out, "removed", format!("{:?}", a.removed), format!("{:?}", b.removed));
    d(&mut out, "despawn", format!("{:?}", a.despawn), format!("{:?}", b.despawn));
    d(&mut out, "gear_knockback_resistance", format!("{:?}", a.gear_knockback_resistance), format!("{:?}", b.gear_knockback_resistance));
    d(&mut out, "fire_ticks", format!("{:?}", a.fire_ticks), format!("{:?}", b.fire_ticks));
    d(&mut out, "ticks_frozen", format!("{:?}", a.ticks_frozen), format!("{:?}", b.ticks_frozen));
    d(&mut out, "in_powder_snow", format!("{:?}", a.in_powder_snow), format!("{:?}", b.in_powder_snow));
    d(&mut out, "air", format!("{:?}", a.air), format!("{:?}", b.air));
    d(&mut out, "first_tick", format!("{:?}", a.first_tick), format!("{:?}", b.first_tick));
    d(&mut out, "was_eye_in_water", format!("{:?}", a.was_eye_in_water), format!("{:?}", b.was_eye_in_water));
    d(&mut out, "age", format!("{:?}", a.age), format!("{:?}", b.age));
    d(&mut out, "ambient_timer", format!("{:?}", a.ambient_timer), format!("{:?}", b.ambient_timer));
    d(&mut out, "persistent", format!("{:?}", a.persistent), format!("{:?}", b.persistent));
    d(&mut out, "no_ai", format!("{:?}", a.no_ai), format!("{:?}", b.no_ai));
    d(&mut out, "silent", format!("{:?}", a.silent), format!("{:?}", b.silent));
    d(&mut out, "swell", format!("{:?}", a.swell), format!("{:?}", b.swell));
    d(&mut out, "previous_swell", format!("{:?}", a.previous_swell), format!("{:?}", b.previous_swell));
    d(&mut out, "max_swell", format!("{:?}", a.max_swell), format!("{:?}", b.max_swell));
    d(&mut out, "random", format!("{:?}", a.random), format!("{:?}", b.random));
    d(&mut out, "fluids", format!("{:?}", a.fluids), format!("{:?}", b.fluids));
    d(&mut out, "ai", format!("{:?}", a.ai), format!("{:?}", b.ai));
    d(&mut out, "attrs", format!("{:?}", a.attrs), format!("{:?}", b.attrs));
    d(&mut out, "anim", format!("{:?}", a.anim), format!("{:?}", b.anim));
    for (name, x, y) in [("extra.age", a.extra.age, b.extra.age), ("extra.in_love", a.extra.in_love, b.extra.in_love)] {
        if x != y {
            out.push(format!("{name}: {x} / {y}"));
        }
    }
    out
}
